// An empty seq inserts nothing (a successful no-op).
func (q *Queries) InsertedIDsStream(ctx context.Context, seq iter.Seq2[NewItem, error]) ([]int64, error) {
	return runtime.Collect(q.InsertedIDsStreamSeq(ctx, seq))
}

